const safe = (value) => {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
};


// Convert AI output into a clean object
function parseAI(value) {

  if (value === null || value === undefined || value === "") {
    return {};
  }

  // Already object
  if (typeof value === "object") {

    // Handle array like [{...}]
    if (Array.isArray(value)) {
      if (value.length === 1 && typeof value[0] === "object") {
        return value[0];
      }

      return {
        value: value
      };
    }

    return value;
  }

  // String
  if (typeof value === "string") {

    let text = value.trim();

    // Remove markdown code fences if AI adds them
    text = text
      .replace(/^```json\s*/i, "")
      .replace(/^```\s*/i, "")
      .replace(/\s*```$/i, "")
      .trim();

    // Try parsing JSON
    try {
      const parsed = JSON.parse(text);

      if (Array.isArray(parsed)) {
        if (parsed.length === 1 && typeof parsed[0] === "object") {
          return parsed[0];
        }

        return {
          value: parsed
        };
      }

      if (typeof parsed === "object") {
        return parsed;
      }

    } catch (e) {
      // Not JSON, return as plain text
      return {
        text: text
      };
    }

    return {
      text: text
    };
  }

  return {
    text: String(value)
  };
}


// Convert AI data into readable text for Google Sheets
function readableText(value) {

  const obj = parseAI(value);

  if (obj.text) {
    return obj.text;
  }

  if (obj.value) {
    return Array.isArray(obj.value)
      ? obj.value.join("; ")
      : String(obj.value);
  }

  return Object.entries(obj)
    .map(([key, value]) => {

      let cleanKey = key
        .replace(/_/g, " ")
        .replace(/\b\w/g, c => c.toUpperCase());

      if (Array.isArray(value)) {
        value = value.join("; ");
      }

      return `${cleanKey}: ${value}`;
    })
    .join(" | ");
}


